let activePanel=null,fleetArmed=false,allianceSignature='',operationSetup=validateSetup({}),setupDraft=null;
try{const saved=JSON.parse(localStorage.getItem('blackout-operation'));if(saved)operationSetup=validateSetup(saved);}catch{}
