function begin(){if(sim.mode==='war'){showSetup();return;}sim.running=true;sim.started=true;updateUI();}
function startOperation(){sim.running=true;sim.started=true;const region=TERRITORIES[sim.playerTeam];renderer.focus(region.center.x,region.center.y,1.8);updateUI();}
function togglePause(){if(sim.ended)return;if(!sim.started){begin();return;}sim.running=!sim.running;updateUI();}
