for(const id of ['manual-dialog','settings-dialog','lab-dialog','setup-dialog'])$(id).addEventListener('close',()=>{if(activeModal===id){activeModal=null;if(resumeAfterModal&&!sim.ended)sim.running=true;resumeAfterModal=false;updateUI();}});
