function modeControls(u){return (MODES[u.type]||[]).map(m=>`<button data-mode="${m.id}" class="mode-button ${u.mode===m.id?'active':''}" ${u.dead||!sim.started||(['launch','nuclear'].includes(m.id)&&sim.phase!==1)?'disabled':''}>${m.name}${u.mode===m.id?' ●':''}</button>`).join('');}
