 const signature=JSON.stringify([u.id,u.hp,u.mode,u.flightPhase,Math.ceil(u.stateTimer),Math.ceil(u.cooldown),u.fighters,u.bombers,u.ammo,u.stockNukes,Math.floor(u.fuel),u.dead,u.landed,!!u.order,u.returning,sim.phase]);if(signature===inspectorSignature)return;inspectorSignature=signature;
 const t=TYPES[u.type],own=u.team===sim.playerTeam,friendly=sim.allied(u.team,sim.playerTeam),base=['carrier','airbase'].includes(u.type),nuclear=['silo','submarine','bomber'].includes(u.type),modes=own&&live(u)?modeControls(u):'',fleet=sim.fleets.find(f=>f.id===u.fleetId),members=fleet?sim.units.filter(v=>fleet.members.includes(v.id)&&live(v)):[];
