$('contacts').onclick=e=>{const b=e.target.closest('[data-contact]');if(!b)return;const u=sim.units.find(u=>u.id===+b.dataset.contact);selectUnit(u);renderer.focus(u.x,u.y,Math.max(renderer.zoom,2.3));};
function updateUI(){
 $('clock').textContent=formatTime(sim.time);$('defcon-number').textContent=sim.phase;$('defcon-name').textContent=phaseNames[sim.phase];$('phase-description').innerHTML=phaseCopy[sim.phase];$('phase-status').textContent=sim.ended?'CEASEFIRE':sim.running?'ACTIVE':'STANDBY';$('pause').textContent=sim.running?'Ⅱ':'▶';$('pause').disabled=!sim.started||sim.ended;$('pause').setAttribute('aria-label',sim.running?'Pause simulation':'Resume simulation');$('begin').disabled=sim.started;$('begin').textContent=sim.ended?'OPERATION ENDED':sim.started?sim.mode==='lab'?'ENGAGEMENT LIVE':'OPERATION LIVE':sim.mode==='lab'?'BEGIN ENGAGEMENT ↗':'BEGIN OPERATION ↗';
 document.querySelectorAll('[data-phase]').forEach(e=>e.classList.toggle('active',+e.dataset.phase===sim.phase));document.body.classList.toggle('high-alert',sim.phase<=2);
 const next=sim.victoryAt!==null?Math.max(0,sim.victoryAt-sim.time):sim.phase===1?null:Math.max(0,PHASE_ENDS[sim.phase]-sim.time);$('next-phase').textContent=next===null?'RELEASED':formatTime(next).slice(3);const previous={5:0,4:360,3:720,2:1200}[sim.phase]||0;$('phase-progress').style.width=sim.phase===1?'100%':`${Math.max(0,Math.min(100,(sim.time-previous)/(PHASE_ENDS[sim.phase]-previous)*100))}%`;
 $('credits').textContent=`${Math.floor(['battleship','carrier','submarine'].reduce((sum,type)=>sum+sim.stock[sim.playerTeam][type],0)/6)} FLEETS LEFT`;$('alive-count').textContent=sim.units.filter(u=>live(u)&&u.team===sim.playerTeam).length;$('nuke-count').textContent=sim.remaining[sim.playerTeam];$('kill-count').textContent=sim.kills[sim.playerTeam];$('casualties').innerHTML=`${sim.losses[sim.playerTeam].toFixed(1)} <small>M</small>`;$('total-casualties').innerHTML=`${sim.losses.reduce((a,b)=>a+b,0).toFixed(1)}<span>M</span>`;$('warheads').textContent=String(sim.missiles.length).padStart(2,'0');$('assessment').textContent=sim.phase>=4?'STABLE':sim.phase===3?'HOSTILITIES':sim.phase===2?'CRITICAL':'CATASTROPHIC';$('midnight').textContent=sim.victoryAt!==null?'VICTORY TIMER ACTIVE':`${sim.phase} MIN TO MIDNIGHT`;$('doomsday-hand').setAttribute('d',`M40 40L${40-3*sim.phase} ${8+sim.phase}`);$('escalate').disabled=sim.phase===1||sim.ended||sim.mode==='lab';
 $('map-hint').innerHTML=deployType?(fleetDraft.length?`PLACE ${fleetDraft.length}-SHIP FLEET IN OPEN WATER`:`PLACE ${TYPES[deployType].name.toUpperCase()} ON LAND`):selectedId?'LEFT CLICK ACTION <span>·</span> RIGHT CLICK MOVE / STATE <span>·</span> SPACE DESELECT':'LEFT CLICK SELECT <span>·</span> RIGHT CLICK MOVE / STATE <span>·</span> SCROLL TO ZOOM';
 if(eventCount!==sim.events[0]?.id){eventCount=sim.events[0]?.id;$('event-log').innerHTML=sim.events.slice(0,30).map(e=>`<div class="log-entry ${e.kind}"><time>${formatTime(e.time)}</time><span>${esc(e.message)}</span></div>`).join('');}renderDeployments();renderContacts();renderInspector();renderAllianceStatus();updateMapControls();
 if(sim.ended&&!resultShown){resultShown=true;$('result-title').textContent=sim.mode==='lab'?(sim.winner===null?'Engagement inconclusive.':`${sim.winner===0?'Allied':'Hostile'} force prevails.`):sim.winner===null?'Nobody won.':sim.allied(sim.winner,sim.playerTeam)?'A costly victory.':'Command has fallen.';$('result-summary').textContent=`${formatTime(sim.time)} elapsed. ${sim.losses.reduce((a,b)=>a+b,0).toFixed(2)} million civilian deaths. Default score: +2 enemy deaths, −1 allied deaths.`;const scores=sim.scores();$('result-stats').innerHTML=[['Your score',scores[sim.playerTeam]],['Leading score',Math.max(...scores)],['Your units lost',sim.unitLosses[sim.playerTeam]],['Enemy units destroyed',sim.kills[sim.playerTeam]],['Warheads launched',sim.totalNukes]].map(([name,value])=>`<div class="status-row"><span>${esc(name)}</span><strong>${value}</strong></div>`).join('');$('result-dialog').showModal();}
}
const presets={naval:['battleship','submarine'],air:['fighter','fighter'],bombing:['battleship','bomber'],nuclear:['nuclear','nuclear'],asw:['submarine','carrier'],hardened:['nuclear','airbase']};
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const[a,c]=presets[b.dataset.preset];$('lab-left').value=a;$('lab-right').value=c;document.querySelectorAll('[data-preset]').forEach(v=>v.classList.toggle('active',v===b));updateLabWarning();});
function updateLabWarning(){const a=$('lab-left').value,b=$('lab-right').value,at=TYPES[a==='nuclear'?'silo':a],bt=TYPES[b==='nuclear'?'silo':b];$('lab-warning').textContent=a==='nuclear'||b==='nuclear'?'Live nuclear strike: installations retain damage between hits. Silos need three direct hits; airbases need two. Defensive silos can intercept incoming warheads.':!at.targets.includes(bt.domain)&&!bt.targets.includes(at.domain)?'These units cannot engage each other directly. Expect a standoff; configure launch states for carriers and airbases.':'Live combat: each naval formation has six ships; aircraft launch from finite carrier decks. The same radar, sonar, missiles, damage and flight rules apply in Global Conflict.';}
$('lab-left').onchange=updateLabWarning;$('lab-right').onchange=updateLabWarning;$('lab-count').oninput=()=>$('lab-count-value').textContent=$('lab-count').value;$('launch-lab').onclick=()=>{resumeAfterModal=false;$('lab-dialog').close();configureSimulation({mode:'lab',left:$('lab-left').value,right:$('lab-right').value,count:+$('lab-count').value});begin();toast('Battle lab uses the gameplay combat engine. Set 20× for faster observation.');};
function stateMenu(u,x,y){selectUnit(u);const modes=MODES[u.type];if(!modes||u.team!==sim.playerTeam)return;const menu=$('state-menu');menu.innerHTML=`<strong>${TYPES[u.type].name} ${u.id}</strong>${modeControls(u)}`;menu.style.left=`${Math.min(innerWidth-205,x)}px`;menu.style.top=`${Math.min(innerHeight-200,y)}px`;menu.showPopover();}
$('state-menu').onclick=e=>{const b=e.target.closest('[data-mode]');if(!b)return;const r=sim.setMode(selectedId,b.dataset.mode);toast(r.ok?'State change ordered.':r.reason);audio.effect(r.ok?'order':'error');closeStateMenu();inspectorSignature='';updateUI();};
let down=null,dragged=false;const point=e=>{const r=$('map').getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};};
$('map').addEventListener('contextmenu',e=>{e.preventDefault();const p=point(e),geo=renderer.unproject(p.x,p.y),u=renderer.pick(sim,p.x,p.y);if(u){stateMenu(u,e.clientX,e.clientY);return;}if(!sim.started){toast('Begin operation and choose your territory before issuing orders.');return;}if(selectedId){const ok=sim.order(selectedId,geo.x,geo.y);toast(ok?'Movement order confirmed. Fleet formation retained.':'Movement unavailable. Naval routes must remain in open water.');audio.effect(ok?'order':'error');updateUI();}});
$('map').addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;const p=point(e);down={...p,px:renderer.pan.x,py:renderer.pan.y,button:e.button};dragged=false;$('map').setPointerCapture(e.pointerId);});
$('map').addEventListener('pointermove',e=>{const p=point(e),geo=renderer.unproject(Math.max(0,Math.min(renderer.width,p.x)),Math.max(0,Math.min(renderer.height,p.y)));renderer.hover=geo;$('map-coordinates').textContent=`${coordinate(geo.y,'N','S')} / ${coordinate(geo.x,'E','W')}`;if(down&&Math.hypot(p.x-down.x,p.y-down.y)>5)dragged=true;if(down&&dragged){renderer.pan.x=down.px+p.x-down.x;renderer.pan.y=down.py+p.y-down.y;renderer.constrain();}});
$('map').addEventListener('pointerup',e=>{if(!down)return;const middle=down.button===1;down=null;if(dragged||middle)return;const p=point(e),geo=renderer.unproject(p.x,p.y),u=renderer.pick(sim,p.x,p.y),own=selected();closeStateMenu();if(deployType){if(fleetDraft.length&&(!fleetArmed||fleetDraft.length!==6)){toast('Fill all six fleet slots and choose Place fleet first.');return;}const r=sim.deploy(deployType,geo.x,geo.y,fleetDraft.length?fleetDraft:null);toast(r.ok?'Units placed. Inventories updated.':r.reason);if(r.ok){fleetDraft=[];fleetArmed=false;deployType=null;renderFleet();closePanel();}audio.effect(r.ok?'order':'error');updateUI();return;}if(sim.ended||!sim.started){selectUnit(u);if(!sim.started)toast('Begin operation to select your territory and alliances.');return;}if(u&&sim.allied(u.team,sim.playerTeam)){selectUnit(u);return;}if(own?.team===sim.playerTeam&&live(own)){let r;if(['silo','submarine','bomber'].includes(own.type)&&['launch','nuclear'].includes(own.mode))r=sim.launch(own.id,geo.x,geo.y,u?.id);else if(['airbase','carrier'].includes(own.type)&&['fighter','bomber'].includes(own.mode))r=sim.launchAircraft(own.id,geo.x,geo.y);else if(u&&sim.hostile(u.team,sim.playerTeam))r={ok:sim.order(own.id,u.x,u.y,u.id),reason:'Target cannot be engaged in the current state.'};else{toast('Right click the map to move. Right click the unit to change state.');return;}toast(r.ok?(r.queued?r.reason:'Primary action confirmed.'):r.reason);audio.effect(r.ok?'order':'error');inspectorSignature='';updateUI();return;}selectUnit(u);});
$('map').addEventListener('pointercancel',()=>down=null);$('map').addEventListener('wheel',e=>{e.preventDefault();const p=point(e);renderer.changeZoom(e.deltaY<0?1.1:1/1.1,p.x,p.y);},{passive:false});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const key=e.key.toLowerCase();if(e.code==='Space'){e.preventDefault();selectUnit(null);}else if(key==='m')$('sound').click();else if(key==='escape'){closePanel();selectUnit(null);toast('Selection cleared.');}else if(['1','2','3','4'].includes(key))setSpeed({1:1,2:5,3:10,4:20}[key]);else if(key==='+'||key==='='||key==='q')renderer.changeZoom(1.2);else if(key==='-'||key==='e')renderer.changeZoom(1/1.2);else if(['arrowleft','arrowright','arrowup','arrowdown','w','a','s','d'].includes(key)){e.preventDefault();if(['arrowleft','a'].includes(key))renderer.pan.x+=45;if(['arrowright','d'].includes(key))renderer.pan.x-=45;if(['arrowup','w'].includes(key))renderer.pan.y+=45;if(['arrowdown','s'].includes(key))renderer.pan.y-=45;renderer.constrain();}});
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;const advance=dt*speed,steps=Math.max(1,Math.ceil(advance/.25));for(let i=0;i<steps;i++)sim.tick(advance/steps);if(sim.ended)for(const blast of sim.blasts)blast.age+=advance;renderer.draw(sim,dt);uiClock+=dt;if(uiClock>.2){uiClock=0;updateUI();}requestAnimationFrame(frame);}
function closePanel(){if(activePanel){const panel=$('panel-'+activePanel);if(panel?.matches(':popover-open'))panel.hidePopover();}activePanel=null;document.querySelectorAll('[data-panel]').forEach(b=>b.setAttribute('aria-expanded','false'));}
function openPanel(name){if(activePanel===name)return;closePanel();const panel=$('panel-'+name);if(!panel)return;panel.showPopover();activePanel=name;document.querySelectorAll('[data-panel]').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.panel===name)));}
document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>{activePanel===b.dataset.panel?closePanel():openPanel(b.dataset.panel);});
document.querySelectorAll('[data-close-panel]').forEach(b=>b.onclick=closePanel);
document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{renderer.setLayer(b.dataset.layer,!renderer.layers[b.dataset.layer]);updateMapControls();});
document.querySelectorAll('[data-grid]').forEach(b=>b.onclick=()=>{renderer.gridMode=b.dataset.grid;updateMapControls();});
$('map-zoom').oninput=()=>{renderer.setZoomPercent(+$('map-zoom').value);updateMapControls();};
$('radar-sharing').onchange=()=>{sim.setRadarSharing($('radar-sharing').checked);allianceSignature='';updateUI();};
$('leave-alliance').onclick=()=>{sim.setAlliance(sim.playerTeam,'independent');allianceSignature='';updateUI();toast('Your faction is now independent.');};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Use your browser fullscreen command to expand the game.');}};
document.addEventListener('fullscreenchange',()=>{$('fullscreen').textContent=document.fullscreenElement?'EXIT FULLSCREEN':'ENTER FULLSCREEN';});
function updateMapControls(){
 renderer.deployTerritory=deployType&&sim.mode==='war'?sim.factions[sim.playerTeam].territory:null;
 $('hud-phase').textContent=sim.phase;$('hud-faction').textContent=sim.mode==='lab'?'BATTLE LAB':sim.started?TERRITORIES[sim.playerTeam].name.toUpperCase():'SELECT TERRITORY';if(sim.mode==='war'){$('theater-label').textContent=sim.started?TERRITORIES[sim.playerTeam].name.toUpperCase():'GLOBAL CONFLICT';$('map-subtitle').textContent=sim.started?`${sim.factionName(sim.playerTeam)} / ${sim.activeTeams().length} FACTIONS`:'SIX TERRITORIES / CHOOSE YOUR COMMAND';}
 $('deployment-territory').textContent=sim.mode==='lab'?'Deployment is disabled in the laboratory.':`${TERRITORIES[sim.playerTeam].name}: ground installations on land; fleets inside your maritime deployment zone. Every fleet requires six ships.`;
 document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',String(renderer.layers[b.dataset.layer])));
 document.querySelectorAll('[data-grid]').forEach(b=>{b.classList.toggle('active',renderer.gridMode===b.dataset.grid);b.setAttribute('aria-pressed',String(renderer.gridMode===b.dataset.grid));});
 $('map-zoom').value=Math.round(renderer.zoomPercent);$('zoom-value').textContent=`${Math.round(renderer.zoomPercent)}%`;
 $('grid-readout').textContent=renderer.gridMode==='mgrs'?`MGRS ${renderer.precision*2} digits (${renderer.precision}E + ${renderer.precision}N) · ${10**(5-renderer.precision)} m reference precision. Zone/band and coordinate labels stay on the axes; lines mark grid zones.`:'Latitude / longitude graticule. Horizontal wrap; vertical pan limits.';
}
function renderAllianceStatus(){const signature=JSON.stringify([sim.factions,sim.radarSharing,sim.started]);if(signature!==allianceSignature){allianceSignature=signature;$('alliance-roster').innerHTML=sim.factions.filter(f=>f.active).map(f=>`<div class="alliance-row"><i class="faction-swatch" style="background:${f.color}"></i><div><strong>${esc(f.name)}</strong><small>${TERRITORIES[f.id].name} / ${ALLIANCES.find(a=>a.id===f.alliance).name}</small></div><span class="relation">${sim.relation(f.id)}</span></div>`).join('');$('radar-sharing').checked=sim.radarSharing;$('leave-alliance').disabled=sim.factions[sim.playerTeam].alliance==='independent';$('map-legend').innerHTML=sim.factions.filter(f=>f.active).map(f=>`<span><i style="background:${f.color}"></i>${TERRITORIES[f.id].name.toUpperCase()}${sim.started&&f.id===sim.playerTeam?' / YOU':''}</span>`).join('');}
 const scores=sim.scores();$('scoreboard').innerHTML=sim.activeTeams().sort((a,b)=>scores[b]-scores[a]).map(team=>`<div class="score-row"><i class="faction-swatch" style="background:${sim.factionColor(team)}"></i><span>${esc(sim.factionName(team))}</span><strong>${scores[team]}</strong></div>`).join('');
}
function showSetup(){setupDraft=structuredClone(operationSetup);renderSetupFields();$('setup-error').hidden=true;openDialog('setup-dialog');drawSetupMap();}
function renderSetupFields(){const player=setupDraft.playerTeam;$('setup-territory').innerHTML=TERRITORIES.map((t,i)=>`<option value="${i}" ${i===player?'selected':''}>${t.name}</option>`).join('');$('setup-name').value=setupDraft.factions[player].name;$('setup-color').value=setupDraft.factions[player].color;$('setup-radar').checked=setupDraft.radarSharing;renderSetupRoster();}
function renderSetupRoster(){const player=setupDraft.playerTeam;$('setup-roster').innerHTML=setupDraft.factions.map((f,i)=>`<div class="setup-roster-row ${f.active?'':'inactive'}"><input type="checkbox" data-active="${i}" aria-label="Activate ${TERRITORIES[i].name}" ${f.active?'checked':''} ${i===player?'disabled':''}><i class="faction-swatch" style="background:${f.color}"></i><span>${TERRITORIES[i].name}<small>${i===player?'YOU / ':f.active?'AI / ':'INACTIVE / '}${esc(f.name)}</small></span><select data-alliance="${i}" aria-label="${TERRITORIES[i].name} alliance" ${!f.active?'disabled':''}>${ALLIANCES.map(a=>`<option value="${a.id}" ${a.id===f.alliance?'selected':''}>${a.name}</option>`).join('')}</select></div>`).join('');}
function chooseTerritory(team){setupDraft.playerTeam=team;setupDraft.factions[team].active=true;renderSetupFields();drawSetupMap();}
$('setup-territory').onchange=()=>chooseTerritory(+$('setup-territory').value);
$('setup-name').oninput=()=>{setupDraft.factions[setupDraft.playerTeam].name=$('setup-name').value;renderSetupRoster();};
$('setup-color').oninput=()=>{setupDraft.factions[setupDraft.playerTeam].color=$('setup-color').value;renderSetupRoster();drawSetupMap();};
$('setup-roster').onchange=e=>{if(e.target.dataset.active!==undefined){setupDraft.factions[+e.target.dataset.active].active=e.target.checked;renderSetupRoster();}if(e.target.dataset.alliance!==undefined)setupDraft.factions[+e.target.dataset.alliance].alliance=e.target.value;drawSetupMap();};
$('setup-radar').onchange=()=>setupDraft.radarSharing=$('setup-radar').checked;
$('authorize-operation').onclick=()=>{try{operationSetup=validateSetup(setupDraft);try{localStorage.setItem('blackout-operation',JSON.stringify(operationSetup));}catch{}resumeAfterModal=false;$('setup-dialog').close();configureSimulation();startOperation();closePanel();toast(`Command transferred to ${TERRITORIES[sim.playerTeam].name}.`);}catch(e){$('setup-error').textContent=e.message;$('setup-error').hidden=false;}};
function drawSetupMap(){if(!setupDraft)return;const canvas=$('setup-map'),rect=canvas.getBoundingClientRect();if(!rect.width)return;const ratio=Math.min(devicePixelRatio||1,2);canvas.width=rect.width*ratio;canvas.height=rect.height*ratio;const c=canvas.getContext('2d');c.setTransform(ratio,0,0,ratio,0,0);const scale=Math.min(rect.width/360,rect.height/180),point=(x,y)=>({x:rect.width/2+x*scale,y:rect.height/2-y*scale});c.fillStyle='#080f14';c.fillRect(0,0,rect.width,rect.height);const path=rings=>{c.beginPath();for(const ring of rings){ring.forEach(([x,y],i)=>{const p=point(x,y);if(i)c.lineTo(p.x,p.y);else c.moveTo(p.x,p.y);});c.closePath();}};
 if(renderer.land){for(const f of renderer.land.features){for(const polygon of f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates){path(polygon);c.fillStyle='#101f28';c.fill('evenodd');c.strokeStyle='#36505c';c.lineWidth=.6;c.stroke();}}}
 for(const f of setupDraft.factions){if(!f.active)continue;const region=territoryMap.regions.find(r=>r.id===f.territory);path(region.rings);c.fillStyle=f.color+(f.id===setupDraft.playerTeam?'55':'1c');c.fill('evenodd');c.strokeStyle=f.color+(f.id===setupDraft.playerTeam?'dd':'6a');c.lineWidth=f.id===setupDraft.playerTeam?1.1:.5;c.stroke();const t=TERRITORIES[f.id],p=point(t.center.x,t.center.y);c.font='8px Consolas,monospace';c.fillStyle=f.color;c.textAlign='center';c.fillText(t.name.toUpperCase(),p.x,p.y);}
}
$('setup-map').onclick=e=>{const rect=$('setup-map').getBoundingClientRect(),scale=Math.min(rect.width/360,rect.height/180),x=(e.clientX-rect.left-rect.width/2)/scale,y=(rect.height/2-(e.clientY-rect.top))/scale,team=territoryMap.at(x,y);if(team>=0)chooseTerritory(team);};

configureSimulation();renderer.ready.then(()=>{if(renderer.land){navigation=new Navigation(renderer.land);sim.navigation=navigation;if($('setup-dialog').open)drawSetupMap();}});requestAnimationFrame(frame);
Object.defineProperty(window,'blackout',{get:()=>({baseline:'v1.43',playerTeam:sim.playerTeam,factions:sim.factions.map(f=>({...f})),radarSharing:sim.radarSharing,cities:sim.cities.map(c=>({...c})),unitLosses:[...sim.unitLosses],layers:{...renderer.layers},grid:{mode:renderer.gridMode,precision:renderer.precision,digits:renderer.precision*2,axisLabels:renderer.axisLabels.map(l=>({...l})),zoom:renderer.zoomPercent},camera:{focus:renderer.unproject(renderer.width/2,renderer.height/2),pan:{...renderer.pan},width:renderer.width,height:renderer.height,worldWidth:renderer.worldWidth,scale:renderer.scale},activePanel,mode:sim.mode,time:sim.time,phase:sim.phase,running:sim.running,ended:sim.ended,units:sim.units.map(u=>({...u,trail:undefined,screen:renderer.project(u.x,u.y)})),fleets:sim.fleets.map(f=>({...f})),losses:[...sim.losses],kills:[...sim.kills],missiles:sim.missiles.map(m=>({...m})),shots:sim.shots.map(s=>({...s,trail:[...s.trail]})),blasts:sim.blasts.map(b=>({...b})),flash:document.body.classList.contains('nuclear-flash'),events:sim.events.slice(0,10),stock:{...sim.stock[sim.playerTeam]},remaining:[...sim.remaining],selectedId,operations:operationRanges(selected()),mapLoaded:!!renderer.land,audioEnabled:audio.enabled,audio:audio.status,speed})});
